function clock(value:number){const seconds=Math.max(0,Math.floor(value/1000)),hours=Math.floor(seconds/3600),minutes=Math.floor(seconds/60)%60;return hours?`${hours}:${String(minutes).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:`${minutes}:${String(seconds%60).padStart(2,'0')}`;}
function ExportOption({id,label,description,icon,disabled,onClick}:{id:string;label:string;description:string;icon:ReactNode;disabled:boolean;onClick:()=>void}) {
 return <button className="export-option" aria-label={label} aria-describedby={`export-description-${id}`} disabled={disabled} onClick={onClick}><span className="export-option-icon" aria-hidden="true">{icon}</span><span className="export-option-copy"><strong>{label}</strong><small id={`export-description-${id}`}>{description}</small></span><ChevronRight className="export-option-arrow" size={16} aria-hidden="true"/></button>;
}
function MinutesText({text}:{text:string}){let fenced=false;return <div className="minutes-reading">{text.split(/\r?\n/).map((line,index)=>{if(/^\s*(```|~~~)/.test(line)){fenced=!fenced;return <p className="minutes-code" key={index}>{line}</p>;}if(fenced)return <p className="minutes-code" key={index}>{line||'\u00a0'}</p>;const heading=/^#{1,3}\s+(.+)$/.exec(line);if(heading)return <h3 key={index}>{heading[1]}</h3>;const quote=/^>\s?(.*)$/.exec(line);if(quote)return <p className="minutes-quote" key={index}>{quote[1]}</p>;const item=/^\s*[-*]\s+(.+)$/.exec(line);if(item)return <p className="minutes-item" key={index}><span aria-hidden="true">•</span>{item[1]}</p>;if(!line.trim())return <div className="minutes-gap" key={index}/>;return <p key={index}>{line}</p>;})}</div>;}
function LongSourceReferences({text,detail,busy,onReview}:{text:string;detail:Detail;busy:boolean;onReview:(quote:string)=>void}) {
 if(/^\s*(`{3,}|~{3,})/m.test(text))return <MinutesText text={text}/>;
 const stale=detail.minutesChanged||detail.transcriptUnreadable||detail.beforeUnreadable;
 const unique=(quote:string)=>uniqueMobileQuote(detail.transcript,quote);
 return <div className="long-source-references"><p className="hint">以下依据来自已保存的纪要。能在原文中唯一匹配的片段可尝试定位到近似回听位置；请结合录音核对。</p>{text.split(/\r?\n/).map((line,index)=>{
  const heading=/^#{1,3}\s+(.+)$/.exec(line);if(heading)return <h4 key={index}>{heading[1]}</h4>;
  const bullet=/^\s*[-*]\s+(.+)$/.exec(line);if(bullet){const quote=bullet[1];const chars=Array.from(quote);const canReview=!stale&&chars.length>=4&&unique(quote);const long=chars.length>160;return <div className="long-source-quote" key={index}>{long?<><p>{chars.slice(0,160).join('')}…</p><details className="minutes-more"><summary>查看完整原话</summary><p>{quote}</p></details></>:<p>{quote}</p>}{canReview&&<button className="text-button" disabled={busy} onClick={()=>onReview(quote)}>查看这条原话的位置 <ChevronRight size={15}/></button>}</div>;}
  return line.trim()?<p key={index}>{line}</p>:<div className="minutes-gap" key={index}/>;
 })}</div>;
}
type MinutesActionControls={onEditAction?:(target:MobileActionTarget)=>void;onToggleAction?:(target:MobileActionTarget,completed:boolean)=>void;onFindAction?:(target:MobileActionTarget,body:string)=>void;readingPreview?:boolean};
function MinutesWithSources({markdown,detail,busy,onReview,onEditAction,onToggleAction,onFindAction,readingPreview=false}:{markdown:string;detail:Detail;busy:boolean;onReview:(quote:string)=>void}&MinutesActionControls) {
 const parsed=splitMobileEvidence(markdown,detail);
 const renderText=(text:string,section?:string,position?:{sectionOccurrence:number;itemOffset:number})=>section==='Action Items'||section==='行动事项'?<MobileActionCards text={text} fallback={<MinutesText text={text}/>} sectionTitle={section} sectionOccurrence={position?.sectionOccurrence??0} itemOffset={position?.itemOffset??0} busy={busy} manualIds={Array.isArray(detail.minutes?.manualReview?.actions)?detail.minutes!.manualReview!.actions!:[]} onEdit={onEditAction} onToggle={onToggleAction} onFind={onFindAction}/>:<MinutesText text={text}/>;
 const generationNote=readingPreview?'本轮使用提前生成的公开录音资料示例，未在本轮调用在线 AI；示例中的修改只在当前预览标签页保留。':detail.minutes?.manualReview?'这份纪要包含人工核对或修改。编辑前的结果可在历史中查看；负责人和时间中的人工安排需要自行确认。':'这是已保存的整理结果，请结合原文核对。重新生成或人工修改时，编辑前的版本会保留在历史中。';
 if(!parsed)return <MinutesDocument markdown={markdown} renderText={renderText} generationNote={generationNote} manualReview={!!detail.minutes?.manualReview} renderSource={text=><LongSourceReferences text={text} detail={detail} busy={busy} onReview={onReview}/>}/>;
 const stale=detail.minutesChanged||detail.transcriptUnreadable||detail.beforeUnreadable;
 return <><MinutesDocument markdown={parsed.overview} renderText={renderText} generationNote={generationNote} manualReview={!!detail.minutes?.manualReview}/><section className="source-evidence" aria-label="原话核对"><h3>原话核对</h3><p>{detail.minutes?.manualReview?'以下原话来自先前 AI 的关联，人工新增内容不属于这些原话，请分别核对。':'以下原话由 AI 关联，仅供核对；关联和转写可能有误。'}</p>{stale&&<p>来源文字已改变或无法读取，暂不能定位，请先核对文字。</p>}{parsed.entries.map((item,index)=><article className="source-evidence-item" key={index}><strong>{item.label}：{item.text}</strong><blockquote>{item.quote}</blockquote><button className="text-button" disabled={busy||stale} onClick={()=>onReview(item.quote)}>查看这条原话的位置 <ChevronRight size={15}/></button></article>)}</section></>;
}
function recordingDate(seconds?:number|null){if(typeof seconds!=='number'||!Number.isSafeInteger(seconds)||seconds<=0||seconds>0xffffffff)return '录音日期未知';return new Intl.DateTimeFormat(undefined,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(seconds*1000));}

